(()=>{'use strict';
const carousel=document.querySelector('.product-carousel');if(carousel){let index=0;const slides=[...carousel.querySelectorAll('.product-slide')],names=slides.map(s=>s.querySelector('h3').textContent);function show(n){index=(n+slides.length)%slides.length;carousel.querySelector('.product-slides').style.transform=`translateX(-${index*100}%)`;slides.forEach((s,i)=>s.setAttribute('aria-hidden',String(i!==index)));document.getElementById('carousel-position').textContent=`${index+1} / ${slides.length} · ${names[index]}`;}carousel.querySelector('[data-carousel-prev]').addEventListener('click',()=>show(index-1));carousel.querySelector('[data-carousel-next]').addEventListener('click',()=>show(index+1));carousel.addEventListener('keydown',e=>{if(e.key==='ArrowRight'||e.key==='ArrowLeft'){e.preventDefault();show(index+(e.key==='ArrowRight'?1:-1));}});let start=null;carousel.addEventListener('touchstart',e=>{start=e.changedTouches[0].clientX;},{passive:true});carousel.addEventListener('touchend',e=>{if(start!==null){const d=e.changedTouches[0].clientX-start;if(Math.abs(d)>45)show(index+(d<0?1:-1));start=null;}},{passive:true});show(0);}
const demo=document.querySelector('.agent-demo');if(!demo)return;const $=id=>document.getElementById(id),reduce=matchMedia('(prefers-reduced-motion: reduce)');let view=0,phase=reduce.matches?2:0,playing=!reduce.matches,visible=false,elapsed=0,last=0;
const views=[{question:'Show admissions and discharges over the week.',title:'Patient flow overview',report:'Admissions and discharges together, grouped by day. A shared view for clinical operations and analytics teams.',type:'line'}, {question:'Create a chart of lab activity by department.',title:'Laboratory activity',report:'Compare incoming result activity by department. Source coverage and definitions should be reviewed before use.',type:'bar'}, {question:'Build a weekly briefing for our CMIO.',title:'Weekly clinical data briefing',report:'A proposed report combining patient flow, laboratory activity and data-quality follow-up. Your team reviews the findings before sharing.',type:'report'}];
const grid='<path d="M40 35H620M40 85H620M40 135H620M40 185H620" stroke="#e2ebe5" fill="none"/>';
function chart(type){let content=grid;if(type==='line'){content+='<path class="series-secondary" d="M40 155L135 145L230 155L325 110L420 115L515 80L620 95"/><path class="series-primary" d="M40 140L135 110L230 125L325 65L420 90L515 45L620 60"/>';['Mon','Tue','Wed','Thu','Fri','Sat','Sun'].forEach((v,i)=>content+=`<text x="${40+i*96}" y="208" text-anchor="middle">${v}</text>`);content+='<text x="40" y="18">Admissions</text><text x="140" y="18">Discharges</text>';}else if(type==='bar'){['ED','Inpatient','Outpatient','Other'].forEach((v,i)=>{const h=[115,145,95,65][i];content+=`<rect class="chart-bar" x="${80+i*140}" y="${185-h}" width="70" height="${h}"/><text x="${115+i*140}" y="208" text-anchor="middle">${v}</text>`;});}else{content='<rect x="25" y="15" width="610" height="205" rx="3" fill="#f4f8f5"/>';['Patient flow: weekly overview','Laboratory activity: department breakdown','Data quality: items for review'].forEach((v,i)=>{content+=`<circle cx="50" cy="${47+i*62}" r="4" fill="#437e68"/><text x="68" y="${51+i*62}">${v}</text><path d="M68 ${66+i*62}H${500-i*55}" stroke="#c8dbce" stroke-width="5"/>`;});}return `<svg viewBox="0 0 660 235" role="img" aria-label="${views[view].title}: illustrative chart, synthetic data, not measured results">${content}</svg>`;}
function render(newView=false){const v=views[view];demo.dataset.phase=String(phase);demo.classList.toggle('stopped',!playing);$('agent-question').textContent=v.question;$('agent-chart-title').textContent=v.title;$('agent-status').textContent=['Reading the approved data','Building your view','Ready for your team to review'][phase];if(newView)$('agent-chart').innerHTML=chart(v.type);$('agent-report').textContent=v.report;document.querySelectorAll('[data-agent-view]').forEach(b=>b.setAttribute('aria-pressed',String(+b.dataset.agentView===view)));$('agent-motion').textContent=playing?'Pause animation Ⅱ':'Play animation ▷';$('agent-motion').setAttribute('aria-pressed',String(!playing));}
document.querySelectorAll('[data-agent-view]').forEach(b=>b.addEventListener('click',()=>{view=+b.dataset.agentView;phase=playing?0:2;elapsed=0;render(true);}));$('agent-motion').addEventListener('click',()=>{playing=!playing;elapsed=0;render();});reduce.addEventListener('change',()=>{playing=!reduce.matches;phase=playing?0:2;render();});if('IntersectionObserver'in window)new IntersectionObserver(es=>{visible=es[0].isIntersecting;demo.classList.toggle('offscreen',!visible);},{threshold:.1}).observe(demo);else visible=true;function tick(now){const dt=Math.min(now-last,100);last=now;if(playing&&visible&&!document.hidden){elapsed+=dt;if(elapsed>(phase===2?5000:2000)){elapsed=0;phase=(phase+1)%3;if(phase===0){view=(view+1)%views.length;render(true);}else render();}}requestAnimationFrame(tick);}render(true);requestAnimationFrame(tick);
})();

(()=>{const campaign=new URLSearchParams(location.search).get('campaign');if(!['google_hl7_fhir_integration','google_healthcare_integration_engine'].includes(campaign))return;document.querySelectorAll('form[data-web3form]').forEach(form=>{const field=document.createElement('input');field.type='hidden';field.name='landing_page';field.value=campaign;form.append(field);});})();
